package app.dayflow.markdown;
import android.widget.TextView;
import io.noties.markwon.*;
import io.noties.markwon.ext.strikethrough.StrikethroughPlugin;
import io.noties.markwon.ext.tasklist.TaskListPlugin;
import io.noties.markwon.ext.tables.TablePlugin;
import io.noties.markwon.ext.latex.JLatexMathPlugin;
import io.noties.markwon.inlineparser.MarkwonInlineParserPlugin;
import io.noties.markwon.image.ImagesPlugin;
import io.noties.markwon.html.HtmlPlugin;
import io.noties.markwon.linkify.LinkifyPlugin;
/** Native CommonMark/GFM preview, bounded image loading and inline/block LaTeX. */
public final class NoteTools {
 private static final java.util.concurrent.ThreadPoolExecutor math=new java.util.concurrent.ThreadPoolExecutor(1,1,20,java.util.concurrent.TimeUnit.SECONDS,new java.util.concurrent.ArrayBlockingQueue<>(64),new java.util.concurrent.ThreadPoolExecutor.AbortPolicy());
 private static final java.util.concurrent.ThreadPoolExecutor images=new java.util.concurrent.ThreadPoolExecutor(2,2,20,java.util.concurrent.TimeUnit.SECONDS,new java.util.concurrent.ArrayBlockingQueue<>(32),new java.util.concurrent.ThreadPoolExecutor.AbortPolicy());
 static{math.allowCoreThreadTimeOut(true);images.allowCoreThreadTimeOut(true);}
 public static void render(TextView view,String markdown){android.content.Context c=view.getContext();try{Markwon.Builder builder=Markwon.builder(c).usePlugin(StrikethroughPlugin.create()).usePlugin(TaskListPlugin.create(Ui.primary(c),Ui.primary(c),Ui.surface(c))).usePlugin(TablePlugin.create(c)).usePlugin(HtmlPlugin.create()).usePlugin(LinkifyPlugin.create(android.text.util.Linkify.WEB_URLS|android.text.util.Linkify.EMAIL_ADDRESSES)).usePlugin(ImagesPlugin.create(plugin->{plugin.executorService(images);plugin.addSchemeHandler(new NoteImages(c));})).usePlugin(new AbstractMarkwonPlugin(){public void configureConfiguration(MarkwonConfiguration.Builder config){config.linkResolver((clicked,link)->{TextView target=view;try{if(link.startsWith("#")){String term=android.net.Uri.decode(link.substring(1)).replace('-',' ').toLowerCase(java.util.Locale.ROOT);int at=target.getText().toString().toLowerCase(java.util.Locale.ROOT).indexOf(term);if(at>=0&&target.getLayout()!=null){int line=target.getLayout().getLineForOffset(at);target.requestRectangleOnScreen(new android.graphics.Rect(0,target.getLayout().getLineTop(line),target.getWidth(),target.getLayout().getLineBottom(line)),false);}return;}android.net.Uri uri=android.net.Uri.parse(link);if(!java.util.Arrays.asList("https","http","mailto","tel","geo","content").contains(uri.getScheme()))throw new IllegalArgumentException();target.getContext().startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW,uri));}catch(Exception e){android.widget.Toast.makeText(target.getContext(),"无法打开此链接",android.widget.Toast.LENGTH_SHORT).show();}});}});if(markdown.contains("$"))builder.usePlugin(MarkwonInlineParserPlugin.create()).usePlugin(JLatexMathPlugin.create(view.getTextSize(),config->{config.inlinesEnabled(true);config.executorService(math);config.theme().textColor(Ui.ink(c));}));builder.build().setMarkdown(view,mathSyntax(footnotes(markdown)));}catch(OutOfMemoryError e){view.setText("设备内存不足以预览此文档，请返回源码编辑；原文未截断。");}catch(RuntimeException e){view.setText(markdown);}}
 private static String footnotes(String value){
  java.util.Map<String,String> notes=new java.util.LinkedHashMap<>();StringBuilder body=new StringBuilder();boolean fence=false;String active=null;
  java.util.regex.Pattern definitionPattern=java.util.regex.Pattern.compile("^\\[\\^([^\\]]+)\\]:\\s*(.*)$");
  for(String line:value.split("\n",-1)){if(line.trim().startsWith("```")||line.trim().startsWith("~~~"))fence=!fence;java.util.regex.Matcher definition=definitionPattern.matcher(line);if(!fence&&notes.size()<128&&definition.matches()){active=definition.group(1);notes.put(active,definition.group(2));continue;}if(!fence&&active!=null&&(line.startsWith("    ")||line.startsWith("\t"))){notes.put(active,notes.get(active)+" "+line.trim());continue;}active=null;body.append(line).append('\n');}
  if(notes.isEmpty())return value;java.util.Map<String,String> markers=new java.util.LinkedHashMap<>();StringBuilder tail=new StringBuilder("\n\n---\n\n");int index=1;for(java.util.Map.Entry<String,String> note:notes.entrySet()){String mark="〔"+(index++)+"〕";markers.put("[^"+note.getKey()+"]",mark);tail.append(mark).append(' ').append(note.getValue()).append("\n\n");}
  StringBuilder text=new StringBuilder();fence=false;for(String line:body.toString().split("\n",-1)){if(line.trim().startsWith("```")||line.trim().startsWith("~~~"))fence=!fence;if(!fence){String[] parts=line.split("`",-1);for(int i=0;i<parts.length;i+=2)for(java.util.Map.Entry<String,String> entry:markers.entrySet())parts[i]=parts[i].replace(entry.getKey(),entry.getValue());line=String.join("`",parts);}text.append(line).append('\n');}return text+tail.toString();
 }
    private static String mathSyntax(String text){StringBuilder out=new StringBuilder();boolean fenced=false;java.util.regex.Pattern inline=java.util.regex.Pattern.compile("(?<![\\\\$])\\$(?![\\s$])([^$\\n]+?)(?<![\\\\\\s])\\$(?![0-9$])");for(String line:text.split("\\n",-1)){String trimmed=line.trim();if(trimmed.startsWith("```")||trimmed.startsWith("~~~"))fenced=!fenced;if(!fenced&&!trimmed.startsWith("$$")){String[] chunks=line.split("`",-1);for(int i=0;i<chunks.length;i+=2){java.util.regex.Matcher matcher=inline.matcher(chunks[i]);StringBuffer result=new StringBuffer();while(matcher.find())matcher.appendReplacement(result,java.util.regex.Matcher.quoteReplacement("$$"+matcher.group(1)+"$$"));matcher.appendTail(result);chunks[i]=result.toString();}line=String.join("`",chunks);}if(out.length()>0)out.append('\n');out.append(line);}return out.toString();}
}
